<div class="page-heading"><div><span class="eyebrow">PIPELINE</span><h1><?= $user['role'] === 'OWNER' ? 'All leads' : 'My leads' ?></h1><p><?= number_format($result['total']) ?> records across your active sales pipeline.</p></div><a class="btn btn-primary" href="<?= e(url('leads/create')) ?>"><i class="bi bi-plus-lg"></i> Create lead</a></div>
<section class="panel"><form class="filter-bar" method="get"><div class="search-box"><i class="bi bi-search"></i><input class="form-control" name="search" value="<?= e((string)($_GET['search'] ?? '')) ?>" placeholder="Search name, company, phone or email"></div><select class="form-select" name="stage"><option value="">All stages</option><?php foreach ($stages as $stage): ?><option value="<?= e($stage) ?>" <?= ($_GET['stage'] ?? '') === $stage ? 'selected' : '' ?>><?= e(ucfirst(strtolower($stage))) ?></option><?php endforeach; ?></select><?php if ($user['role'] === 'OWNER'): ?><select class="form-select" name="assigned_to"><option value="">All BDEs</option><?php foreach ($bdes as $bde): ?><option value="<?= (int)$bde['id'] ?>" <?= (int)($_GET['assigned_to'] ?? 0)===(int)$bde['id']?'selected':'' ?>><?= e($bde['name']) ?></option><?php endforeach; ?></select><?php endif; ?><input type="date" class="form-control" name="follow_up_date" value="<?= e((string)($_GET['follow_up_date'] ?? '')) ?>" aria-label="Follow-up date"><button class="btn btn-dark">Apply</button><a class="btn btn-light" href="<?= e(url('leads')) ?>" aria-label="Reset filters"><i class="bi bi-arrow-counterclockwise"></i></a></form>
<div class="table-responsive"><table class="table align-middle lead-table"><thead><tr><th>Lead</th><th>Contact</th><th>Assigned BDE</th><th>Stage</th><th>Next follow-up</th><th>Last activity</th><th></th></tr></thead><tbody><?php foreach ($result['rows'] as $lead): ?><tr><td><a class="lead-name" href="<?= e(url('leads/'.$lead['id'])) ?>"><?= e($lead['name']) ?></a><small><?= e($lead['company_name'] ?: $lead['city'] ?: 'Independent lead') ?></small></td><td><span><?= e($lead['phone']) ?></span><small><?= e($lead['email']) ?></small></td><td><?= e($lead['assigned_name'] ?: 'Unassigned') ?></td><td><span class="stage-badge stage-<?= e(strtolower($lead['stage'])) ?>"><?= e(ucfirst(strtolower($lead['stage']))) ?></span></td><td><?php if ($lead['next_follow_up']): ?><strong class="<?= substr($lead['next_follow_up'],0,10)<date('Y-m-d')&&!in_array($lead['stage'],['WON','LOST'],true)?'text-danger':'' ?>"><?= e(date('d M Y', strtotime($lead['next_follow_up']))) ?></strong><small><?= e(date('g:i A', strtotime($lead['next_follow_up']))) ?></small><?php else: ?><span class="text-secondary">Not scheduled</span><?php endif; ?></td><td><?= $lead['last_activity'] ? e(date('d M, g:i A', strtotime($lead['last_activity']))) : '—' ?></td><td><a class="btn btn-sm btn-light" href="<?= e(url('leads/'.$lead['id'])) ?>" aria-label="View <?= e($lead['name']) ?>"><i class="bi bi-arrow-right"></i></a></td></tr><?php endforeach; ?><?php if (! $result['rows']): ?><tr><td colspan="7"><div class="empty-state"><i class="bi bi-search"></i><p>No leads match these filters.</p></div></td></tr><?php endif; ?></tbody></table></div>
<?php if ($result['pages'] > 1): ?><nav class="pagination-wrap" aria-label="Lead pages"><span>Page <?= $result['page'] ?> of <?= $result['pages'] ?></span><div><?php $query=$_GET; if ($result['page']>1): $query['page']=$result['page']-1; ?><a class="btn btn-sm btn-light" href="?<?= e(http_build_query($query)) ?>">Previous</a><?php endif; ?><?php if ($result['page']<$result['pages']): $query['page']=$result['page']+1; ?><a class="btn btn-sm btn-dark" href="?<?= e(http_build_query($query)) ?>">Next</a><?php endif; ?></div></nav><?php endif; ?></section>
